SELECT u.id, u.username, u.real_name, u.phone, u.email, u.avatar, u.gender, u.user_type, u.school_id, u.status, u.remark, u.create_time, s.school_name FROM sys_user u LEFT JOIN school s ON u.school_id = s.id
u.deleted = 0
AND u.username LIKE CONCAT('%', #{query.username}, '%')
AND u.real_name LIKE CONCAT('%', #{query.realName}, '%')
AND u.phone = #{query.phone}
AND u.user_type = #{query.userType}
AND u.school_id = #{query.schoolId}
AND u.status = #{query.status}
AND EXISTS ( SELECT 1 FROM sys_user_role ur WHERE ur.user_id = u.id AND ur.role_id = #{query.roleId} )
ORDER BY u.create_time DESC

SELECT role_id
FROM sys_user_role
WHERE user_id = #{userId}
